        DailyQuestion(id: 161, text: LText(de: "Was war die schönste Überraschung, die du je von mir bekommen hast?", en: "What's the loveliest surprise you've ever gotten from me?")),
        DailyQuestion(id: 162, text: LText(de: "Was würdest du an einem perfekten Freitagabend anziehen — nur für mich?", en: "What would you wear on a perfect Friday night — just for me?")),
        DailyQuestion(id: 163, text: LText(de: "Welche Sprache würdest du gern mit mir zusammen lernen?", en: "Which language would you like to learn together with me?")),
        DailyQuestion(id: 164, text: LText(de: "Was hat dich heute genervt — und was hat geholfen?", en: "What annoyed you today — and what helped?")),
        DailyQuestion(id: 165, text: LText(de: "Wann hast du zuletzt gedacht: „Genau deshalb liebe ich mein Leben“?", en: "When did you last think, \"This is exactly why I love my life\"?")),
        DailyQuestion(id: 166, text: LText(de: "Was würdest du gern besser können?", en: "What do you wish you were better at?")),
        DailyQuestion(id: 167, text: LText(de: "Welches gemeinsame Foto sollten wir nachstellen?", en: "Which photo of us should we recreate?")),
        DailyQuestion(id: 168, text: LText(de: "Was macht dich an unserer Zukunft am meisten neugierig?", en: "What makes you most curious about our future?")),
        DailyQuestion(id: 169, text: LText(de: "In welchem Moment heute hast du dich mir besonders nah gefühlt?", en: "In which moment today did you feel especially close to me?")),
        DailyQuestion(id: 170, text: LText(de: "Welchen Rat würdest du frisch verliebten Paaren geben?", en: "What advice would you give newly-in-love couples?")),
        DailyQuestion(id: 171, text: LText(de: "Was hättest du heute fast vergessen?", en: "What did you almost forget today?")),
        DailyQuestion(id: 172, text: LText(de: "Womit habe ich dich zuletzt so richtig beeindruckt?", en: "What did I last really impress you with?")),
        DailyQuestion(id: 173, text: LText(de: "Welche Kleinigkeit im Alltag macht dich unverhältnismäßig glücklich?", en: "What everyday little thing makes you disproportionately happy?")),
        DailyQuestion(id: 174, text: LText(de: "Was möchtest du am liebsten sofort mit mir teilen, wenn etwas Gutes passiert?", en: "What do you most want to share with me right away when something good happens?")),
        DailyQuestion(id: 175, text: LText(de: "Was war der schönste Satz, den du heute gehört oder gelesen hast?", en: "What was the most beautiful sentence you heard or read today?")),
        DailyQuestion(id: 176, text: LText(de: "Wenn du mir eine Playlist für morgen früh machen würdest — welcher Song wäre der erste?", en: "If you made me a playlist for tomorrow morning — what would the first song be?")),
        DailyQuestion(id: 177, text: LText(de: "Welchen unserer Pläne sollten wir endlich umsetzen?", en: "Which of our plans should we finally make happen?")),
        DailyQuestion(id: 178, text: LText(de: "Wovon möchtest du heute Nacht träumen?", en: "What do you want to dream about tonight?")),
        DailyQuestion(id: 179, text: LText(de: "Was würdest du tun, wenn du dich einen Tag lang in mich verwandeln könntest?", en: "What would you do if you could turn into me for a day?")),
        DailyQuestion(id: 180, text: LText(de: "Welche Erinnerung von uns würdest du in einer Zeitkapsel vergraben?", en: "Which memory of us would you bury in a time capsule?")),
        DailyQuestion(id: 181, text: LText(de: "Wo würdest du mich gerade am liebsten küssen — Stirn, Wange oder Lippen?", en: "Where would you most like to kiss me right now — forehead, cheek, or lips?")),
        DailyQuestion(id: 182, text: LText(de: "Was macht dir gerade ein bisschen Sorgen — und wie kann ich helfen?", en: "What's worrying you a little at the moment — and how can I help?")),
        DailyQuestion(id: 183, text: LText(de: "Welcher Tag mit mir würde als „bester Tag ever“ in dein Tagebuch kommen?", en: "Which day with me would go down in your diary as the \"best day ever\"?")),
        DailyQuestion(id: 184, text: LText(de: "Was war heute dein Soundtrack — welcher Song lief rauf und runter?", en: "What was your soundtrack today — which song was on repeat?")),
        DailyQuestion(id: 185, text: LText(de: "Was möchtest du mir sagen, bevor der Tag zu Ende geht?", en: "What do you want to tell me before the day ends?")),
        DailyQuestion(id: 186, text: LText(de: "Welches Emoji beschreibt unsere Beziehung diese Woche am besten — und warum?", en: "Which emoji describes our relationship this week best — and why?")),
        DailyQuestion(id: 187, text: LText(de: "Wenn wir jetzt sofort ins Auto steigen würden — wohin sollte unser Spontan-Trip gehen?", en: "If we hopped in the car right now — where should our spontaneous trip take us?")),
        DailyQuestion(id: 188, text: LText(de: "Welche kleine Geste von mir sollte ich viel öfter machen?", en: "Which little gesture of mine should I do way more often?")),
        DailyQuestion(id: 189, text: LText(de: "Womit kann ich dich nach einem anstrengenden Tag am schnellsten aufmuntern?", en: "What's the fastest way for me to cheer you up after an exhausting day?")),
        DailyQuestion(id: 190, text: LText(de: "Welcher Song müsste im Abspann eines Films über uns laufen?", en: "Which song would have to play over the closing credits of a movie about us?")),
        DailyQuestion(id: 191, text: LText(de: "Welche Frage wolltest du mir immer schon stellen, hast dich aber nie getraut?", en: "Which question have you always wanted to ask me but never dared to?")),
        DailyQuestion(id: 192, text: LText(de: "Beschreibe uns als Paar in genau drei Worten.", en: "Describe us as a couple in exactly three words.")),
        DailyQuestion(id: 193, text: LText(de: "Wenn heute unser erstes Date gewesen wäre — was hätte dich von einem zweiten überzeugt?", en: "If today had been our first date — what would have convinced you to go on a second one?")),
        DailyQuestion(id: 194, text: LText(de: "Was hat dich diese Woche stolz auf uns gemacht?", en: "What made you proud of us this week?")),
        DailyQuestion(id: 195, text: LText(de: "Wenn du mir jetzt einen Brief schreiben würdest — wie würde der erste Satz lauten?", en: "If you wrote me a letter right now — what would the first sentence be?")),
        DailyQuestion(id: 196, text: LText(de: "Welchen Ort in unserer Nähe sollten wir zu unserem Stammplatz erklären?", en: "Which spot near us should we make our regular place?")),
        DailyQuestion(id: 197, text: LText(de: "Womit könnte ich dich morgen früh am schönsten überraschen?", en: "What would be the loveliest way for me to surprise you tomorrow morning?")),
        DailyQuestion(id: 198, text: LText(de: "Welcher Moment mit mir hat sich zuletzt wie Magie angefühlt?", en: "Which recent moment with me felt like magic?")),
        DailyQuestion(id: 199, text: LText(de: "Was möchtest du nächste Woche zum ersten Mal mit mir ausprobieren?", en: "What do you want to try with me for the first time next week?")),
        DailyQuestion(id: 200, text: LText(de: "Welches Geräusch oder welcher Geruch erinnert dich sofort an mich?", en: "Which sound or smell instantly reminds you of me?")),
        DailyQuestion(id: 201, text: LText(de: "Was würdest du unserem jüngeren Ich über uns erzählen, wenn du eine Minute Zeit hättest?", en: "If you had one minute, what would you tell our younger selves about us?")),
        DailyQuestion(id: 202, text: LText(de: "Bei welcher gemeinsamen Aufgabe sind wir das beste Team?", en: "At which shared task are we the best team?")),
        DailyQuestion(id: 203, text: LText(de: "Welchen Mini-Luxus sollten wir uns viel öfter zusammen gönnen?", en: "Which little luxury should we treat ourselves to together way more often?")),
        DailyQuestion(id: 204, text: LText(de: "Was hast du heute gesehen, das ich bestimmt auch geliebt hätte?", en: "What did you see today that I definitely would have loved too?")),
        DailyQuestion(id: 205, text: LText(de: "Welche Jahreszeit fühlt sich am meisten nach uns an — und warum?", en: "Which season feels the most like us — and why?")),
        DailyQuestion(id: 206, text: LText(de: "Worüber würdest du gern mal eine ganze Nacht mit mir reden?", en: "What would you love to talk with me about for a whole night?")),
        DailyQuestion(id: 207, text: LText(de: "Welche Superkraft hätte unsere Beziehung, wenn sie eine Superheldin wäre?", en: "If our relationship were a superhero, what would its superpower be?")),
        DailyQuestion(id: 208, text: LText(de: "Was war das Mutigste, das wir bisher zusammen gemacht haben?", en: "What's the bravest thing we've done together so far?")),
        DailyQuestion(id: 209, text: LText(de: "Welchen kleinen Moment von heute möchtest du dir für immer merken?", en: "Which small moment from today do you want to remember forever?"))
    ]
}
